// Rat v3 (T035): the redrawn rat (A026 + A027 round 1, docs/design/rigs/rat-v3-plan.md), three-quarter view only, as the
// raider's viewer compare version `v3` (src/viewer/models.js). Not in the game's registry: the game's rat is rat-raider.js.
// Parts, points and limits: rat-v3-parts.js, GENERATED by the importer on the user's fitted joints (re-run it after Art's
// next round: the command is in tools/rig_from_source.py). Every piece is drawn whole on the master canvas, so rest 0 = the
// A017 master, as the raider: his poses play on it by joint name (tail-1 is the standard's `tail`).
// limits: { part: [lo, hi] } degrees from rest, + clockwise on screen (the user's Fitting Room ranges); render/limits.js
//   keeps every drawn joint inside them, and the pose page's drags too.
// retarget (T035 r2): each frame the raider (the spearman for his moves) is laid out with the pose, held item and grips,
//   and v3's hands and feet go where his are (render/retarget.js); the torso, neck, waist and tail keep their angles.
// order: the source's drawOrder (hand over forearm, foot over shin, near arm over torso, seat over thigh) on the raider's
//   band numbers, so a pose's band override (`order`) means the same depth on both rats.
// T039: A028's hand, head and foot swaps (same names as the raider's, so his poses' swaps show on v3; split grips draw
//   [under, item, face] as his: render/grip-split.js). Holds as the raider's (slots, heldHand, two-hand / bow grips), on
//   v3's own grip lines: rat-v3-grip-lines.js, GENERATED by tools/v3-grip-lines.mjs from the user's lines when
//   docs/design/rigs/grip-lines-rat-v3.json exists (it does: round 2), Art's A028 handle lines without it. The round
//   shield straps on hand-far-shield's line (the user's, along the strap: render/strap.js).
import PARTS from './rat-v3-parts.js';
import * as LINES from './rat-v3-grip-lines.js';
import { withGripLines } from './grip-lines.js';
import { A021_HOLDS } from '../items/a021-holds.js';
import raiderPoses from './rat-raider-poses.js';
import raider from './rat-raider.js';
import spearman from './rat-spearman.js';
import { RAIDER, SPEARMAN, PLACES, withOwn } from './rat-v3-poses.js';
import { V3_IMPACT } from '../impact.js';

export const BANDS = {
  'tail-3': 60, 'tail-2': 70, tail: 80, 'scarf-tail': 90, 'arm-far-lower': 110, 'arm-far-upper': 120, 'hand-far': 125,   // A027 r2: far upper arm over the forearm's top
  'leg-far-lower': 210, 'foot-far': 215, 'leg-far-upper': 220, pelvis: 400, 'leg-near-lower': 510, 'foot-near': 515,
  'leg-near-upper': 520, seat: 540, torso: 600, belt: 640, head: 700, 'arm-near-upper': 810, 'arm-near-lower': 820, 'hand-near': 830,
};

const EAR = [119.8, 176.8];   // full bow draw: the raider's EAR (head px) at the same offset from v3's neck point
const RIG = {
  ...PARTS,
  sockets: { ...PARTS.sockets, carry: { between: ['hand_near', 'hand_far'] } },   // T028 carry socket, as the raider's
  carry: { order: 660 },
  hands: {}, heldHand: { 'hand-near': 'hand-near-grip' },
  // the held item just behind the fist it hangs from (v3's hands are at 830 / 125), as the raider's (815 / 115 -> 812 / 112)
  slots: { 'one-hand': { parent: 'hand-near', order: 827 }, 'two-hand': { parent: 'hand-near', order: 827 }, bow: { parent: 'hand-far', order: 122 } },
  grips: {
    'two-hand': { swap: { 'hand-far': 'hand-far-grip-overhand' }, order: { 'hand-far': 845, 'arm-far-lower': 848 }, wrist: 'above',
      ik: { arm: ['arm-far-upper', 'arm-far-lower'], end: 'hand-far', to: 'grip2' } },
    bow: { swap: { 'hand-far': 'hand-far-grip', 'hand-near': 'hand-near-pinch' }, arrow: 810, string: 805, anchor: { part: 'head', at: EAR },
      ik: { arm: ['arm-near-upper', 'arm-near-lower'], end: 'hand-near', to: 'nock' } },
  },
  parts: Object.fromEntries(Object.entries(PARTS.parts).map(([n, p]) => [n, { ...p, order: BANDS[n] ?? p.order }])),
  // T039 r2: v3 has no whole guard-arm drawing, so where a pose draws the raider's far upper arm over the chest (guard,
  // shield bash: GUARD_FRONT) v3's jointed forearm and hand (and the shield riding the hand) go there with it
  bandWith: { 'arm-far-lower': 'arm-far-upper', 'hand-far': 'arm-far-upper' },
  springs: { parts: { tail: 0.6, 'tail-2': 0.8, 'tail-3': 1, 'scarf-tail': 0.8 } },   // as the raider's
  poses: withOwn(raiderPoses, RAIDER),   // T040: v3's own places for the moves the retarget can't carry (rat-v3-poses.js)
  places: PLACES,
  retarget: { ...raider, poses: raiderPoses },
  impact: V3_IMPACT,   // T041: overshoot and stretch on its attacks (data/impact.js; the raider's own clips have none)   // T035 r2: the raider's poses by where his hands and feet are (render/retarget.js), not by angle
};
// v3 holding by grip lines G (the format of rat-v3-grip-lines.js; tools/v3-grip-ends.mjs tries both ways of Art's lines)
export const withLines = (G) => withGripLines(RIG, G, ['rat-cutlass', 'plank-club', 'big-fish', 'rat-spear', 'rat-bow', 'mouse-sword', 'rat-arrow', ...Object.keys(A021_HOLDS)],
  Object.fromEntries(Object.entries(A021_HOLDS).map(([id, d]) => [id, d.size])));
const HELD = withLines(LINES);
export default HELD;
// the spearman's moves (spear thrust, staff work) on the same body: the spearman's compare version `v3`
// T039 r2: the spear and staff stay in v3's near side grip (not the spearman's overhand `holds`): his stance folds the
// near forearm up, and v3's near wrist (-49..9) can't turn the overhand fist off the forearm, so the shaft would run
// back along it (169 deg off his, 123 in the side grip): v3 needs its own spear stance (T039 r2 report)
// T041: its spear and staff keys pose the item (item-led: rat-v3-poses.js SPEARMAN, render/item-lead.js)
export const V3_SPEARMAN = { ...HELD, poses: withOwn(spearman.poses, SPEARMAN), retarget: spearman, itemPoses: true };
